CREATE SCHEMA IF NOT EXISTS inventory;

CREATE TABLE IF NOT EXISTS inventory.transfers (
    id UUID NOT NULL DEFAULT gen_random_uuid(),
    name TEXT NOT NULL DEFAULT '/',
    origin TEXT,
    note TEXT,
    priority priority NOT NULL DEFAULT 'normal',
    picking_type_id UUID NOT NULL,
    location_id UUID NOT NULL,
    location_dest_id UUID NOT NULL,
    partner_id UUID,
    company_id UUID NOT NULL,
    move_type move_type NOT NULL DEFAULT 'direct',
    scheduled_date TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    date_done TIMESTAMPTZ,
    state transfer_state NOT NULL DEFAULT 'draft',
    is_locked BOOLEAN NOT NULL DEFAULT TRUE,
    backorder_id UUID,
    return_id UUID,
    metadata JSONB NOT NULL DEFAULT '{"created_at":null,"updated_at":null,"deleted_at":null,"created_by":null,"updated_by":null,"deleted_by":null}'::jsonb,
    PRIMARY KEY (id)
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_transfers_name_company_id ON inventory.transfers (name, company_id) WHERE (metadata->>'deleted_at') IS NULL;

CREATE INDEX IF NOT EXISTS idx_transfers_state ON inventory.transfers (state);

CREATE INDEX IF NOT EXISTS idx_transfers_picking_type_id ON inventory.transfers (picking_type_id);

CREATE INDEX IF NOT EXISTS idx_transfers_scheduled_date ON inventory.transfers (scheduled_date);

CREATE INDEX IF NOT EXISTS idx_transfers_partner_id ON inventory.transfers (partner_id);

CREATE INDEX IF NOT EXISTS idx_transfers_backorder_id ON inventory.transfers (backorder_id);

CREATE INDEX IF NOT EXISTS idx_transfers_return_id ON inventory.transfers (return_id);

CREATE INDEX IF NOT EXISTS idx_transfers_company_id ON inventory.transfers (company_id);

-- GIN index for audit metadata JSONB queries
CREATE INDEX IF NOT EXISTS idx_transfers_metadata_gin ON inventory.transfers USING GIN (metadata);
CREATE INDEX IF NOT EXISTS idx_transfers_metadata_deleted_at ON inventory.transfers ((metadata->>'deleted_at'));
CREATE INDEX IF NOT EXISTS idx_transfers_metadata_created_at ON inventory.transfers ((metadata->>'created_at'));
CREATE INDEX IF NOT EXISTS idx_transfers_metadata_updated_at ON inventory.transfers ((metadata->>'updated_at'));

-- Triggers for automatic metadata timestamp management
-- Automatically sets created_at on INSERT and updated_at on UPDATE

-- Function to set metadata->'created_at' on INSERT
CREATE OR REPLACE FUNCTION inventory.transfers_audit_timestamp() RETURNS trigger AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        NEW.metadata = jsonb_set(NEW.metadata::jsonb, '{created_at}', to_jsonb(NOW()));
        NEW.metadata = jsonb_set(NEW.metadata::jsonb, '{updated_at}', to_jsonb(NOW()));
    ELSIF TG_OP = 'UPDATE' THEN
        NEW.metadata = jsonb_set(NEW.metadata::jsonb, '{updated_at}', to_jsonb(NOW()));
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Trigger to set timestamps on INSERT
DROP TRIGGER IF EXISTS transfers_insert_audit ON inventory.transfers;
CREATE TRIGGER transfers_insert_audit BEFORE INSERT ON inventory.transfers
    FOR EACH ROW EXECUTE FUNCTION inventory.transfers_audit_timestamp();

-- Trigger to set updated_at on UPDATE
DROP TRIGGER IF EXISTS transfers_update_audit ON inventory.transfers;
CREATE TRIGGER transfers_update_audit BEFORE UPDATE ON inventory.transfers
    FOR EACH ROW EXECUTE FUNCTION inventory.transfers_audit_timestamp();
